/*
 * LegacyVault - V14 (PS-41)
 * Purpose:
 *   - Store the digitized legal-basis document of a dossier version (encrypted, like will files), because ST-18 requires the
 *     document to be digitized and hashed. file_reference stays NOT NULL and is generated by the server.
 *   - Record the legal basis type (NOTARIAL_PARTITION, COURT_JUDGMENT, COURT_DECISION).
 *   - At most one dossier per verification case.
 * Notes:
 *   - New columns are nullable so existing rows (none expected) are not affected.
 *   - Constraints that use the new columns are created in later batches (separate GO) so SQL Server sees the columns first.
 */
IF COL_LENGTH(N'dbo.legal_basis_dossier_versions', N'legal_basis_type') IS NULL
    ALTER TABLE dbo.legal_basis_dossier_versions ADD legal_basis_type NVARCHAR(30) NULL;
GO
IF COL_LENGTH(N'dbo.legal_basis_dossier_versions', N'original_file_name') IS NULL
    ALTER TABLE dbo.legal_basis_dossier_versions ADD original_file_name NVARCHAR(255) NULL;
GO
IF COL_LENGTH(N'dbo.legal_basis_dossier_versions', N'content_type') IS NULL
    ALTER TABLE dbo.legal_basis_dossier_versions ADD content_type NVARCHAR(150) NULL;
GO
IF COL_LENGTH(N'dbo.legal_basis_dossier_versions', N'file_size_bytes') IS NULL
    ALTER TABLE dbo.legal_basis_dossier_versions ADD file_size_bytes BIGINT NULL;
GO
IF COL_LENGTH(N'dbo.legal_basis_dossier_versions', N'encrypted_file_content') IS NULL
    ALTER TABLE dbo.legal_basis_dossier_versions ADD encrypted_file_content VARBINARY(MAX) NULL;
GO
IF COL_LENGTH(N'dbo.legal_basis_dossier_versions', N'encryption_iv') IS NULL
    ALTER TABLE dbo.legal_basis_dossier_versions ADD encryption_iv BINARY(12) NULL;
GO
IF COL_LENGTH(N'dbo.legal_basis_dossier_versions', N'encryption_key_version') IS NULL
    ALTER TABLE dbo.legal_basis_dossier_versions ADD encryption_key_version NVARCHAR(50) NULL;
GO
IF NOT EXISTS (
    SELECT 1 FROM sys.check_constraints
    WHERE name = N'CK_legal_basis_dossier_versions_basis_type'
      AND parent_object_id = OBJECT_ID(N'dbo.legal_basis_dossier_versions')
)
    ALTER TABLE dbo.legal_basis_dossier_versions ADD CONSTRAINT CK_legal_basis_dossier_versions_basis_type
        CHECK (legal_basis_type IS NULL
               OR legal_basis_type IN (N'NOTARIAL_PARTITION', N'COURT_JUDGMENT', N'COURT_DECISION'));
GO
IF NOT EXISTS (
    SELECT 1 FROM sys.check_constraints
    WHERE name = N'CK_legal_basis_dossier_versions_encryption_fields'
      AND parent_object_id = OBJECT_ID(N'dbo.legal_basis_dossier_versions')
)
    ALTER TABLE dbo.legal_basis_dossier_versions ADD CONSTRAINT CK_legal_basis_dossier_versions_encryption_fields
        CHECK ((encrypted_file_content IS NULL AND encryption_iv IS NULL AND encryption_key_version IS NULL)
            OR (encrypted_file_content IS NOT NULL AND encryption_iv IS NOT NULL AND encryption_key_version IS NOT NULL));
GO
IF NOT EXISTS (
    SELECT 1 FROM sys.indexes
    WHERE name = N'UX_legal_basis_dossiers_case'
      AND object_id = OBJECT_ID(N'dbo.legal_basis_dossiers')
)
    CREATE UNIQUE INDEX UX_legal_basis_dossiers_case ON dbo.legal_basis_dossiers(verification_case_id);
GO
